/**
 * generate-nuclear-audio.mjs
 * Generates ElevenLabs narration for the NuclearPlant composition.
 *
 * Usage:
 *   $env:ELEVENLABS_API_KEY="your_key_here"; node scripts/generate-nuclear-audio.mjs
 *
 * Outputs:
 *   public/audio/nuclear/title.mp3
 *   public/audio/nuclear/slide-1.mp3  ...  public/audio/nuclear/slide-4.mp3
 *   src/nuclear-durations.ts  (auto-generated, do not edit)
 *
 * Voice: George (British male, calm and authoritative)
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const API_KEY = process.env.ELEVENLABS_API_KEY;
if (!API_KEY) {
  console.error("❌  Set ELEVENLABS_API_KEY environment variable first.");
  console.error("    PowerShell: $env:ELEVENLABS_API_KEY=\"sk-...\"");
  process.exit(1);
}

// George — British male, calm and authoritative
const VOICE_ID = "JBFqnCBsd6RMkjVDRZzb";
const MODEL_ID = "eleven_multilingual_v2";

const NARRATIONS = [
  {
    id: "title",
    text: "The Nuclear Power Plant. What does it really mean when God destroys?",
  },
  {
    id: "slide-1",
    text: "Imagine a small town built near a nuclear power plant. The plant's technician is brilliant and dedicated — and utterly despised by those he serves. The townspeople resent his presence. They want him gone. But he remains at his post every day, because he understands what they cannot: his constant vigilance is the only thing keeping the reactor from destroying them.",
  },
  {
    id: "slide-2",
    text: "One day, the townspeople have had enough. They march to the plant and physically remove him. He offers no resistance — he cannot impose his protection on those who have rejected it. He simply walks away. In that moment, with no one left to maintain the systems, the reactor begins to destabilize.",
  },
  {
    id: "slide-3",
    text: "The plant explodes. The town is devastated. And now ask the question that changes everything: who is responsible? Not the technician. He did not set off the explosion. He did not retaliate. He was simply absent — because they had expelled him. He is not the destroyer. He was prevented from being the savior.",
  },
  {
    id: "slide-4",
    text: "F.T. Wright sees God in that technician. When the Bible says God destroyed Sodom, sent the flood, or brought plagues on Egypt — Wright asks us to look again. In each case, God was the one being pushed out. The destruction that followed was not divine punishment. It was sin's natural, self-destructive consequence, unfolding in the absence of the only One capable of preventing it.",
  },
];

const OUTPUT_DIR = path.resolve("public/audio/nuclear");
fs.mkdirSync(OUTPUT_DIR, { recursive: true });

// ── List voices (optional) ────────────────────────────────────────────────────
if (process.argv.includes("--list-voices")) {
  const res = await fetch("https://api.elevenlabs.io/v1/voices", {
    headers: { "xi-api-key": API_KEY },
  });
  const { voices } = await res.json();
  console.log("\nAvailable voices:");
  for (const v of voices) {
    console.log(`  ${v.voice_id}  ${v.name}  (${v.labels?.accent ?? ""} ${v.labels?.gender ?? ""})`);
  }
  process.exit(0);
}

// ── Generate audio ────────────────────────────────────────────────────────────
console.log(`\nGenerating ${NARRATIONS.length} audio clips...\n`);

for (const { id, text } of NARRATIONS) {
  const outPath = path.join(OUTPUT_DIR, `${id}.mp3`);
  process.stdout.write(`  ${id} ... `);

  const res = await fetch(
    `https://api.elevenlabs.io/v1/text-to-speech/${VOICE_ID}`,
    {
      method: "POST",
      headers: {
        "xi-api-key": API_KEY,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        text,
        model_id: MODEL_ID,
        voice_settings: {
          stability: 0.55,
          similarity_boost: 0.75,
          style: 0.2,
          use_speaker_boost: true,
        },
      }),
    }
  );

  if (!res.ok) {
    const err = await res.text();
    console.error(`FAILED (${res.status}): ${err}`);
    continue;
  }

  const buffer = Buffer.from(await res.arrayBuffer());
  fs.writeFileSync(outPath, buffer);
  console.log(`✓  saved (${(buffer.length / 1024).toFixed(0)} KB)`);
}

// ── Write nuclear-durations.ts ────────────────────────────────────────────────
const BITRATE_BPS = 128_000;
const CORRECTION = 0.974;

const slideIds = NARRATIONS.filter((n) => n.id !== "title").map((n) => n.id);
const durationsS = slideIds.map((id) => {
  const file = path.join(OUTPUT_DIR, `${id}.mp3`);
  const bytes = fs.statSync(file).size;
  return parseFloat(((bytes * 8) / BITRATE_BPS * CORRECTION).toFixed(3));
});

const today = new Date().toISOString().slice(0, 10);
const tsContent = `/**
 * AUTO-GENERATED by scripts/generate-nuclear-audio.mjs — do not edit manually.
 * Re-run the script after regenerating audio to update these values.
 * Last generated: ${today} (George voice, eleven_multilingual_v2)
 */

// Estimated durations in seconds (file size ÷ 128kbps × 0.974 correction).
export const NUCLEAR_SLIDE_DURATIONS_S: number[] = [
${slideIds.map((id, i) => {
  const slide = NARRATIONS.find((n) => n.id === id);
  return `  ${durationsS[i]}, // ${id} — ${slide?.text.split(" ").slice(0, 5).join(" ")}...`;
}).join("\n")}
];
`;

const durationsFile = path.resolve(__dirname, "../src/nuclear-durations.ts");
fs.writeFileSync(durationsFile, tsContent);
console.log(`\n✅  Done. Durations written to src/nuclear-durations.ts`);
console.log("    The dev server will hot-reload automatically.\n");
